// Deterministic pseudo-random numbers.
//
// The sopa de letras must be reproducible from its seed: the same seed always yields
// the same grid, so a variant can be re-verified and never has to be regenerated by
// playing, printing, reloading or restoring. Math.random() would break that, so this
// module provides a small seeded generator (mulberry32) instead.

/** FNV-1a over the string, as an unsigned 32-bit integer. */
export function hashSeed(value) {
	const text = String(value ?? "");
	let hash = 2166136261;
	for (let index = 0; index < text.length; index += 1) {
		hash ^= text.charCodeAt(index);
		hash = Math.imul(hash, 16777619);
	}
	return hash >>> 0;
}

export function createPrng(seed) {
	let state = typeof seed === "number" ? seed >>> 0 : hashSeed(seed);
	if (state === 0) state = 0x9e3779b9;
	const next = () => {
		state = (state + 0x6d2b79f5) >>> 0;
		let value = state;
		value = Math.imul(value ^ (value >>> 15), value | 1);
		value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
		return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
	};
	return {
		next,
		/** Integer in [0, max). */
		int(max) {
			if (!Number.isFinite(max) || max <= 0) return 0;
			return Math.floor(next() * max);
		},
		pick(list) {
			if (!Array.isArray(list) || list.length === 0) return undefined;
			return list[Math.floor(next() * list.length)];
		},
		/** Fisher-Yates over a copy, so callers keep their arrays intact. */
		shuffle(list) {
			const copy = [...(list ?? [])];
			for (let index = copy.length - 1; index > 0; index -= 1) {
				const swap = Math.floor(next() * (index + 1));
				[copy[index], copy[swap]] = [copy[swap], copy[index]];
			}
			return copy;
		},
	};
}
